def listar(s, caminho, filtros, tamanho=100):
    regs, pagina = [], 1
    while True:
        r = s.get(BASE + caminho, params={**filtros, 'page': pagina, 'pageSize': tamanho}, timeout=120)
        r.raise_for_status()
        corpo = r.json()
        regs += corpo.get('items', [])
        if not corpo.get('hasNext'):
            return regs
        pagina += 1

